  collectDependency(dep: any, debugInfo?: any): any {
    this.runTrackCoordination(dep, debugInfo)
    if (!activeSub || !shouldTrack) {
      return
    }

    let link = dep.activeLink
    if (link === undefined || link.sub !== activeSub) {
      link = dep.activeLink = {
        dep,
        sub: activeSub,
        version: dep.version,
        nextDep: undefined,
        prevDep: undefined,
        nextSub: undefined,
        prevSub: undefined,
        prevActiveLink: undefined,
      }

      if (!activeSub.deps) {
        activeSub.deps = activeSub.depsTail = link
      } else {
        link.prevDep = activeSub.depsTail
        activeSub.depsTail!.nextDep = link
        activeSub.depsTail = link
