      for (let link = dep.subs; link; link = link.prevSub) {
        link.sub.notify()
      }
    } finally {
      endBatch()
    }
  }

  bumpDepAndNotify(
    dep: any,
    debugInfo: any,
    bumpEpoch: () => number,
  ): void {
    dep.version++
    const next = bumpEpoch()
    this.syncReactiveEpoch(next)
    this.notifyDependencySubscribers(dep, debugInfo)
  }

  trackReactiveProperty(
    target: object,
    type: any,
    key: unknown,
    targetMap: WeakMap<object, Map<any, any>>,
    createDep: () => any,
  ): void {
    this.runTrackCoordination(target, key)
    if (shouldTrack && activeSub) {
      let depsMap = targetMap.get(target)
      if (!depsMap) {
        targetMap.set(target, (depsMap = new Map()))
      }
      let dep = depsMap.get(key)
      if (!dep) {
        depsMap.set(key, (dep = createDep()))
      }
      if (__DEV__) {
        dep.track({
          target,
          type,
          key,
        })
      } else {
        dep.track()
      }
    }
  }

  dispatchPropertyTrigger(
    target: object,
    type: any,
    key: unknown,
    newValue: unknown,
    oldValue: unknown,
    oldTarget: any,
    targetMap: WeakMap<object, Map<any, any>>,
    iterateKey: any,
    mapKeyIterateKey: any,
    arrayIterateKey: any,
    bumpEpoch: () => number,
  ): void {
    this.runNotifyCoordination(target, key)
    const depsMap = targetMap.get(target)
    if (!depsMap) {
      const next = bumpEpoch()
      this.syncReactiveEpoch(next)
      return
    }

    let deps: any[] = []
    if (type === 'clear') {
      deps = [...depsMap.values()]
    } else {
      const targetIsArray = isArray(target)
      const isArrayIndex = targetIsArray && isIntegerKey(key)

      if (targetIsArray && key === 'length') {
        const newLength = Number(newValue)
        depsMap.forEach((dep, depKey) => {
          if (
            depKey === 'length' ||
            depKey === arrayIterateKey ||
            (!isSymbol(depKey) && depKey >= newLength)
          ) {
            deps.push(dep)
          }
        })
      } else {
        const push = (dep: any | undefined) => {
          if (dep) {
            deps.push(dep)
          }
        }

        if (key !== void 0) {
          push(depsMap.get(key))
        }

        if (isArrayIndex) {
          push(depsMap.get(arrayIterateKey))
        }

        switch (type) {
          case 'add':
            if (!targetIsArray) {
              push(depsMap.get(iterateKey))
              if (isMap(target)) {
                push(depsMap.get(mapKeyIterateKey))
              }
            } else if (isArrayIndex) {
              push(depsMap.get('length'))
            }
            break
          case 'delete':
            if (!targetIsArray) {
              push(depsMap.get(iterateKey))
              if (isMap(target)) {
                push(depsMap.get(mapKeyIterateKey))
              }
            }
            break
          case 'set':
            if (isMap(target)) {
              push(depsMap.get(iterateKey))
            }
            break
        }
      }
    }

    startBatch()
    for (const dep of deps) {
      if (__DEV__) {
        dep.trigger({
          target,
          type,
          key,
          newValue,
          oldValue,
          oldTarget,
        })
      } else {
        dep.trigger()
      }
    }
    endBatch()
  }

  markComputedDirty(computed: any): void {
    this.runComputedCoordination(computed)
    if (activeSub !== computed) {
